6	import { AUTOSAVE_INTERVAL_MS, HOTBAR_SLOTS, MAX_HUNGER, MAX_HEARTS, MAX_OXYGEN, SAVE_KEY } from "@/lib/game/config";
7	import { GameEngine } from "@/lib/game/engine/GameEngine";
8	import type { GameApi, GameSnapshot } from "@/lib/game/engine/state";
9	import { createInputController, type InputController } from "@/lib/game/input/inputController";
10	import * as inv from "@/lib/game/inventory";
11	import { DEFAULT_SKIN_ID, getSkinPreset, type SkinId } from "@/lib/game/playerSkins";
12	import { readSkinSettings, writeSkinSettings } from "@/lib/game/skinSettings";
13	import { createEmptyArmorEquipment, createInitialInventory, ITEM_DEF_BY_ID } from "@/lib/game/items";
14	import { RECIPES } from "@/lib/game/recipes";
15	import { GameRenderer } from "@/lib/game/render/GameRenderer";
16	import { createMinimapRenderer, type MinimapRenderer } from "@/lib/game/render/minimap";
17	import { readSave, writeSave } from "@/lib/game/save";
18	import type { Recipe } from "@/lib/game/types";
19	
20	/**
21	 * Thin React shell around the headless GameEngine and the GameRenderer.
22	 *
23	 * The engine is created in the canvas mount's callback ref (commit phase) and
24	 * held in React state; the UI reads it through useSyncExternalStore snapshots
25	 * and sends intents back as engine commands. The effect below owns everything
26	 * with a lifecycle: renderer, input listeners, the rAF loop, and autosave.
27	 */
28	
29	// Pre-mount snapshot (also the SSR snapshot): the starter loadout at full stats.
30	const PRE_MOUNT_SNAPSHOT: GameSnapshot = {
31	  api: null,
32	  inventory: createInitialInventory(),
33	  equippedArmor: createEmptyArmorEquipment(),
34	  selectedSlot: 0,
35	  hearts: MAX_HEARTS,
36	  hunger: MAX_HUNGER,
37	  oxygen: MAX_OXYGEN,
38	  daylightPercent: 100,
39	  passiveCount: 0,
40	  hostileCount: 0,
41	  respawnSeconds: 0,
42	  inventoryOpen: false,
43	  paused: false,
44	  debugOpen: false,
45	  debug: null,
46	  cameraMode: "first",
47	  armorPoints: 0,
48	  capsActive: false,
49	  sleeping: false,
50	  craftingStation: null,
51	  container: null,
52	  boss: null,
53	  victory: false
54	};
55	
56	const noopSubscribe = () => () => {};
57	
58	type GameContext = { engine: GameEngine; node: HTMLDivElement };
59	
60	// Debug/test handle: lets the browser console and the Playwright E2E suite
61	// inspect the live simulation (single-player client game — nothing to protect).
62	declare global {
63	  interface Window {
64	    __monecraft?: { engine: GameEngine; renderer: GameRenderer; input: InputController; audio: AudioDirector };
65	  }
66	}
67	
68	function persistGame(api: GameApi, onMessage: (text: string) => void): void {
69	  try {
70	    writeSave(SAVE_KEY, api.serialize());
71	    onMessage("Saved");
72	  } catch {
73	    onMessage("Save failed");
74	  }
75	}
76	
77	export function useMinecraftGame() {
78	  const [ctx, setCtx] = useState<GameContext | null>(null);
79	  const [locked, setLocked] = useState(false);
80	  const [saveMessage, setSaveMessage] = useState("");
81	  const [rendererError, setRendererError] = useState<string | null>(null);
82	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
83	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
84	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
85	  const audioRef = useRef<AudioDirector | null>(null);
86	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
87	  const audioSettingsRef = useRef(audioSettings);
88	  const [skinId, setSkinId] = useState<SkinId>(DEFAULT_SKIN_ID);
89	  const skinIdRef = useRef(skinId);
90	  const rendererRef = useRef<GameRenderer | null>(null);
91	
92	  // Persisted preferences load after mount: render never touches localStorage
93	  // (SSR), and the setState hops a microtask like the renderer-error report.
94	  // This effect runs before the renderer effect (ctx is set by a callback ref
95	  // in a later commit), so the refs are populated by the time either exists.
96	  useEffect(() => {
97	    const stored = readAudioSettings();
98	    audioSettingsRef.current = stored;
99	    audioRef.current?.setSettings(stored);
100	    const { skinId: storedSkin } = readSkinSettings();
101	    skinIdRef.current = storedSkin;
102	    queueMicrotask(() => {
103	      setAudioSettings(stored);
104	      setSkinId(storedSkin);
105	    });
106	  }, []);
107	
108	  const updateAudioSettings = useCallback((partial: Partial<AudioSettings>) => {
109	    const next = { ...audioSettingsRef.current, ...partial };
110	    audioSettingsRef.current = next;
111	    setAudioSettings(next);
112	    writeAudioSettings(next);
113	    audioRef.current?.setSettings(next);
114	  }, []);
115	
116	  const updateSkin = useCallback((id: SkinId) => {
117	    skinIdRef.current = id;
118	    setSkinId(id);
119	    writeSkinSettings({ skinId: id });
120	    rendererRef.current?.setPlayerSkin(getSkinPreset(id).palette);
121	  }, []);
122	
123	  // Callback ref: the engine boots as soon as the canvas mount exists. A ref
124	  // callback runs during commit, where side effects and setState are legal.
125	  const attachMount = useCallback((node: HTMLDivElement | null) => {
126	    if (!node) {
127	      setCtx(null);
128	      return;
129	    }
130	    setCtx({ engine: new GameEngine({ save: readSave(SAVE_KEY) }), node });
131	  }, []);
132	
133	  // The minimap container mounts independently of the canvas; the rAF loop
134	  // below picks it up lazily once both exist.
135	  const attachMinimap = useCallback((node: HTMLDivElement | null) => {
136	    minimapNodeRef.current = node;
137	  }, []);
138	
139	  const engine = ctx?.engine ?? null;
140	  const subscribe = useMemo(() => engine?.subscribe ?? noopSubscribe, [engine]);
141	  const getSnapshot = useMemo(() => engine?.getSnapshot ?? (() => PRE_MOUNT_SNAPSHOT), [engine]);
142	  const getServerSnapshot = useCallback(() => PRE_MOUNT_SNAPSHOT, []);
143	  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
144	
145	  const flashMessage = useCallback((text: string, durationMs = 1200) => {
146	    setSaveMessage(text);
147	    window.setTimeout(() => setSaveMessage(""), durationMs);
148	  }, []);
149	
150	  useEffect(() => {
151	    if (!ctx) return;
152	    const { engine: gameEngine, node } = ctx;
153	
154	    const created = GameRenderer.create(node);
155	    if (!created.ok) {
156	      // Microtask: reporting an init failure from inside the effect body
157	      // would count as a cascading synchronous setState.
158	      queueMicrotask(() => setRendererError(created.error));
159	      return;
160	    }
161	    const renderer = created.renderer;
162	    canvasRef.current = renderer.domElement;
163	    rendererRef.current = renderer;
164	    // Before the first rAF, so no frame can ever show the default palette.
165	    renderer.setPlayerSkin(getSkinPreset(skinIdRef.current).palette);
166	
167	    const audio = createAudioDirector();
168	    audio.setSettings(audioSettingsRef.current);
169	    audioRef.current = audio;
170	    const input = createInputController({
171	      canvas: renderer.domElement,
172	      engine: gameEngine,
173	      onResize: () => renderer.handleResize(),
174	      onLockChange: (isLocked) => {
175	        // Pointer-lock acquisition is itself a user gesture — a safe unlock
176	        // point, and it re-resumes a context suspended by the browser.
177	        if (isLocked) audio.unlock();
178	        setLocked(isLocked);
179	      }
180	    });
181	
182	    // Autoplay policy: the AudioContext may only start inside a user gesture.
183	    const unlockAudio = () => audio.unlock();
184	    document.addEventListener("mousedown", unlockAudio);
185	    document.addEventListener("keydown", unlockAudio);
186	
187	    const autoSave = () => persistGame(gameEngine, flashMessage);
188	    const autoSaveId = window.setInterval(autoSave, AUTOSAVE_INTERVAL_MS);
189	    window.addEventListener("beforeunload", autoSave);
190	
191	    window.__monecraft = { engine: gameEngine, renderer, input, audio };
192	
193	    let minimap: MinimapRenderer | null = null;
194	    let last = performance.now();
195	    let animationFrame = 0;
196	    // Catch-up stepping: a slow frame (software GL, busy machine) can take far
197	    // longer than one 50ms step, and a single clamped step would run the
198	    // simulation in slow motion. Bounded substeps keep sim time tracking wall
199	    // time; the cap bounds work per frame and quietly drops time beyond it
200	    // (e.g. after a background-tab stall).
201	    const MAX_STEP_SECONDS = 0.05;
202	    const MAX_SUBSTEPS = 5;
203	    let pendingSeconds = 0;
204	    const clock = () => {
205	      const now = performance.now();
206	      pendingSeconds = Math.min(pendingSeconds + (now - last) / 1000, MAX_STEP_SECONDS * MAX_SUBSTEPS);
207	      last = now;
208	
209	      let frameSeconds = 0;
210	      while (pendingSeconds > 0) {
211	        const dt = Math.min(pendingSeconds, MAX_STEP_SECONDS);
212	        gameEngine.step(dt, input.input);
213	        pendingSeconds -= dt;
214	        frameSeconds += dt;
215	      }
216	
217	      for (const event of gameEngine.consumeEvents()) {
218	        if (event.type === "died" || event.type === "bossDefeated") {
219	          // Free the cursor so the death/victory button is clickable; the pause
220	          // command ignores both states, so the lock-loss won't open the menu too.
221	          input.clearKeys();
222	          if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
223	        }
224	        if (event.type === "respawned") input.clearKeys();
225	        if (event.type === "attackSwung") renderer.triggerSwing();
226	        if (event.type === "openedStation" || event.type === "openedContainer") {
227	          // A furnace/chest opened the inventory from a mouse click — release the
228	          // keys and pointer lock the same way KeyI does on the DOM side.
229	          input.clearKeys();
230	          if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
231	        }
232	        if (event.type === "breakBlocked") {
233	          flashMessage("Not enough room to empty the chest");
234	        }
235	        if (event.type === "sleepDenied") {
236	          flashMessage(event.reason === "daylight" ? "You can only sleep at night" : "Monsters are nearby");
237	        }
238	        if (event.type === "pickedUp") {
239	          flashMessage(event.items.map((drop) => `+${drop.count} ${ITEM_DEF_BY_ID[drop.itemId]?.label ?? drop.itemId}`).join(", "));
240	        }
241	        if (event.type === "summonFailed") {
242	          flashMessage("The totem lies dormant — a beast already walks");
243	        }
244	        renderer.handleEvent(event, gameEngine.state);
245	        audio.handleEvent(event);
246	      }
247	
248	      if (!minimap && minimapNodeRef.current) minimap = createMinimapRenderer(minimapNodeRef.current);
249	      // The minimap must read worldMeshDirty before renderer.sync clears it.
250	      minimap?.sync(gameEngine.state, now);
251	      renderer.sync(gameEngine.state, now);
252	      audio.sync(gameEngine.state, frameSeconds);
253	      renderer.render();
254	      animationFrame = requestAnimationFrame(clock);
255	    };
256	    animationFrame = requestAnimationFrame(clock);
257	
258	    return () => {
259	      delete window.__monecraft;
260	      canvasRef.current = null;
261	      rendererRef.current = null;
262	      minimap?.dispose();
263	      cancelAnimationFrame(animationFrame);
264	      window.clearInterval(autoSaveId);
265	      window.removeEventListener("beforeunload", autoSave);
266	      document.removeEventListener("mousedown", unlockAudio);
267	      document.removeEventListener("keydown", unlockAudio);
268	      audioRef.current = null;
269	      audio.dispose();
270	      input.dispose();
271	      document.exitPointerLock();
272	      renderer.dispose();
273	    };
274	  }, [ctx, flashMessage]);
275	
276	  // Re-locking can legitimately reject (e.g. Chrome's cooldown right after
277	  // Escape); the player just clicks the canvas to lock again.
278	  const requestPointerLock = useCallback(() => {
279	    const canvas = canvasRef.current;
280	    if (canvas) Promise.resolve(canvas.requestPointerLock()).catch(() => {});
281	  }, []);
282	
283	  return {
284	    attachMount,
285	    attachMinimap,
286	    locked,
287	    rendererError,
288	    selectedSlot: snapshot.selectedSlot,
289	    setSelectedSlot: (index: number) => engine?.dispatch({ type: "selectSlot", index }),
290	    capsActive: snapshot.capsActive,
291	    inventoryOpen: snapshot.inventoryOpen,
292	    inventory: snapshot.inventory,
293	    equippedArmor: snapshot.equippedArmor,
294	    armorPoints: snapshot.armorPoints,
295	    hearts: snapshot.hearts,
296	    hunger: snapshot.hunger,
297	    oxygen: snapshot.oxygen,
298	    daylightPercent: snapshot.daylightPercent,
299	    passiveCount: snapshot.passiveCount,
300	    hostileCount: snapshot.hostileCount,
301	    respawnSeconds: snapshot.respawnSeconds,
302	    paused: snapshot.paused,
303	    sleeping: snapshot.sleeping,
304	    craftingStation: snapshot.craftingStation,
305	    container: snapshot.container,
306	    boss: snapshot.boss,
307	    victory: snapshot.victory,
308	    debugOpen: snapshot.debugOpen,
309	    debug: snapshot.debug,
310	    saveMessage,
311	    audioSettings,
312	    updateAudioSettings,
313	    skinId,
314	    updateSkin,
315	    hotbarSlots: HOTBAR_SLOTS,
316	    recipes: RECIPES,
317	    maxHearts: MAX_HEARTS,
318	    maxHunger: MAX_HUNGER,
319	    maxOxygen: MAX_OXYGEN,
320	    canCraft: (recipe: Recipe) => inv.canCraft(snapshot.inventory, recipe),
321	    craft: (recipe: Recipe) => engine?.dispatch({ type: "craft", recipeId: recipe.id }),
322	    swapInventorySlots: (from: number, to: number) => engine?.dispatch({ type: "swapSlots", from, to }),
323	    moveStack: (from: number, to: number) => engine?.dispatch({ type: "moveStack", from, to }),
324	    toggleEquipArmor: (index: number) => engine?.dispatch({ type: "toggleEquipArmor", index }),
325	    resumeNow: () => {
326	      engine?.dispatch({ type: "resume" });
327	      requestPointerLock();
328	    },
329	    respawnNow: () => engine?.dispatch({ type: "respawn" }),
330	    dismissVictory: () => engine?.dispatch({ type: "dismissVictory" }),
331	    saveNow: () => {
332	      if (engine) persistGame(engine, flashMessage);
333	    },
334	    loadNow: () => {
335	      if (!readSave(SAVE_KEY)) {
336	        flashMessage("No save found", 1400);
337	        return;
338	      }
339	      flashMessage("Loaded");
340	      window.setTimeout(() => window.location.reload(), 120);
341	    },
342	    resetNow: () => {
343	      try {
344	        localStorage.removeItem(SAVE_KEY);
345	        setSaveMessage("Resetting...");
346	        window.setTimeout(() => window.location.reload(), 500);
347	      } catch {
348	        flashMessage("Reset failed");
349	      }
350	    }
351	  };
352	}
