1	/**
2	 * Worlds — the second level of the save hierarchy. Each world belongs to one
3	 * profile (`profileId`) and owns a single bundled SaveData blob under its own
4	 * `minecraft_world_save_<id>` key (read/written with the existing
5	 * lib/game/save.ts helpers). The world *index* — names, seeds, ordering — lives
6	 * in one versioned manifest blob; the heavy per-world saves stay separate so
7	 * the index reads cheaply.
8	 *
9	 * A world's `seed` is resolved once at creation and is the source of truth for
10	 * regeneration; `worldgenVersion` records the WORLDGEN_VERSION it was generated
11	 * under so a future baseline bump can discard its stale block-diffs.
12	 */
13	
14	import { WORLDGEN_VERSION } from "./config";
15	import { readManifestRaw, resolveDeps, sanitizeName, writeManifest, type ManifestDeps } from "./manifest";
16	
17	export type WorldMeta = {
18	  id: string;
19	  profileId: string;
20	  name: string;
21	  seed: number;
22	  worldgenVersion: number;
23	  createdAt: number;
24	  lastPlayedAt: number;
25	};
26	
27	export type WorldsManifest = {
28	  version: 1;
29	  worlds: WorldMeta[];
30	};
31	
32	export const WORLDS_KEY = "minecraft_worlds_v1";
33	export const WORLD_SAVE_PREFIX = "minecraft_world_save_";
34	export const MAX_WORLD_NAME = 32;
35	export const DEFAULT_WORLD_NAME = "New World";
36	export const MAX_SEED = 2147483647;
37	
38	export const DEFAULT_WORLDS_MANIFEST: WorldsManifest = { version: 1, worlds: [] };
39	
40	/** The per-world SaveData key handed to readSave/writeSave. */
41	export function worldSaveKey(worldId: string): string {
42	  return WORLD_SAVE_PREFIX + worldId;
43	}
44	
45	/** FNV-1a hash of a text seed into a stable non-negative 31-bit integer (Minecraft-style). */
46	export function hashStringToSeed(text: string): number {
47	  let hash = 0x811c9dc5;
48	  for (let i = 0; i < text.length; i += 1) {
49	    hash ^= text.charCodeAt(i);
50	    hash = Math.imul(hash, 0x01000193);
51	  }
52	  return Math.abs(hash | 0) % MAX_SEED;
53	}
54	
55	/**
56	 * Resolves a user seed input to an integer in 0..MAX_SEED-1: blank → random
57	 * (same entropy the engine used for a fresh world), numeric text → clamped int,
58	 * any other text → stable hash. `rng` is injectable for deterministic tests.
59	 */
60	export function resolveSeed(seedInput: string | null, rng: () => number = Math.random): number {
61	  const trimmed = (seedInput ?? "").trim();
62	  if (trimmed === "") return Math.floor(rng() * MAX_SEED);
63	  const asNumber = Number(trimmed);
64	  if (Number.isFinite(asNumber)) return Math.floor(Math.abs(asNumber)) % MAX_SEED;
65	  return hashStringToSeed(trimmed);
66	}
67	
68	/** Coerces one raw entry into a valid WorldMeta, or null if it can't be salvaged. */
69	function sanitizeWorld(raw: unknown): WorldMeta | null {
70	  if (!raw || typeof raw !== "object") return null;
71	  const entry = raw as Record<string, unknown>;
72	  if (typeof entry.id !== "string" || entry.id.length === 0) return null;
73	  if (typeof entry.profileId !== "string" || entry.profileId.length === 0) return null;
74	  if (typeof entry.seed !== "number" || !Number.isFinite(entry.seed)) return null;
75	  const num = (value: unknown, fallback: number) => (typeof value === "number" && Number.isFinite(value) ? value : fallback);
76	  return {
77	    id: entry.id,
78	    profileId: entry.profileId,
79	    name: sanitizeName(entry.name, DEFAULT_WORLD_NAME, MAX_WORLD_NAME),
80	    seed: Math.floor(entry.seed),
81	    worldgenVersion: num(entry.worldgenVersion, WORLDGEN_VERSION),
82	    createdAt: num(entry.createdAt, 0),
83	    lastPlayedAt: num(entry.lastPlayedAt, 0)
84	  };
85	}
86	
87	/** Reads the worlds manifest, dropping malformed entries. Never throws. */
88	export function readWorlds(storage: Storage = localStorage): WorldsManifest {
89	  const raw = readManifestRaw(WORLDS_KEY, storage) as Partial<WorldsManifest> | null;
90	  if (!raw || !Array.isArray(raw.worlds)) return { ...DEFAULT_WORLDS_MANIFEST };
91	  return { version: 1, worlds: raw.worlds.map(sanitizeWorld).filter((w): w is WorldMeta => w !== null) };
92	}
93	
94	export function getWorld(id: string, storage: Storage = localStorage): WorldMeta | null {
95	  return readWorlds(storage).worlds.find((w) => w.id === id) ?? null;
96	}
97	
98	/** A profile's worlds, most-recently-played first (ties broken by creation time). */
99	export function worldsForProfile(profileId: string, storage: Storage = localStorage): WorldMeta[] {
100	  return readWorlds(storage)
101	    .worlds.filter((w) => w.profileId === profileId)
102	    .sort((a, b) => b.lastPlayedAt - a.lastPlayedAt || b.createdAt - a.createdAt);
103	}
104	
105	/** Creates a world for a profile, persists it, and returns it. `deps.rng` seeds blank-input worlds. */
106	export function createWorld(profileId: string, name: string, seedInput: string | null, deps: ManifestDeps & { rng?: () => number } = {}): WorldMeta {
107	  const { storage, now, uid } = resolveDeps(deps);
108	  const createdAt = now();
109	  const world: WorldMeta = {
110	    id: uid(),
111	    profileId,
112	    name: sanitizeName(name, DEFAULT_WORLD_NAME, MAX_WORLD_NAME),
113	    seed: resolveSeed(seedInput, deps.rng ?? Math.random),
114	    worldgenVersion: WORLDGEN_VERSION,
115	    createdAt,
116	    lastPlayedAt: createdAt
117	  };
118	  const manifest = readWorlds(storage);
119	  writeManifest(WORLDS_KEY, { version: 1, worlds: [...manifest.worlds, world] }, storage);
120	  return world;
121	}
122	
123	export function renameWorld(id: string, name: string, storage: Storage = localStorage): WorldsManifest {
124	  const manifest = readWorlds(storage);
125	  const next: WorldsManifest = {
126	    version: 1,
127	    worlds: manifest.worlds.map((w) => (w.id === id ? { ...w, name: sanitizeName(name, w.name, MAX_WORLD_NAME) } : w))
128	  };
129	  writeManifest(WORLDS_KEY, next, storage);
130	  return next;
131	}
132	
133	/** Bumps a world's `lastPlayedAt` so it sorts to the top of its profile's list. */
134	export function touchWorld(id: string, deps: ManifestDeps = {}): WorldsManifest {
135	  const { storage, now } = resolveDeps(deps);
136	  const manifest = readWorlds(storage);
137	  const next: WorldsManifest = {
138	    version: 1,
139	    worlds: manifest.worlds.map((w) => (w.id === id ? { ...w, lastPlayedAt: now() } : w))
140	  };
141	  writeManifest(WORLDS_KEY, next, storage);
142	  return next;
143	}
144	
145	/** Removes a world from the index and deletes its save blob. */
146	export function deleteWorld(id: string, storage: Storage = localStorage): WorldsManifest {
147	  const manifest = readWorlds(storage);
148	  const next: WorldsManifest = { version: 1, worlds: manifest.worlds.filter((w) => w.id !== id) };
149	  writeManifest(WORLDS_KEY, next, storage);
150	  try {
151	    storage.removeItem(worldSaveKey(id));
152	  } catch {
153	    // A failed blob cleanup just leaves an orphaned key; the index no longer references it.
154	  }
155	  return next;
156	}
157	
158	/** Cascade for profile deletion: removes every world of a profile and its save blobs. */
159	export function deleteWorldsForProfile(profileId: string, storage: Storage = localStorage): WorldsManifest {
160	  const manifest = readWorlds(storage);
161	  const doomed = manifest.worlds.filter((w) => w.profileId === profileId);
162	  const next: WorldsManifest = { version: 1, worlds: manifest.worlds.filter((w) => w.profileId !== profileId) };
163	  writeManifest(WORLDS_KEY, next, storage);
164	  for (const world of doomed) {
165	    try {
166	      storage.removeItem(worldSaveKey(world.id));
167	    } catch {
168	      // Orphaned blob; the index no longer references it.
169	    }
170	  }
171	  return next;
172	}

